<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<?php $trades = array(); foreach ($crews as $crew) if ($crew->source_trade) $trades[$crew->source_trade] = $crew->source_trade; ksort($trades); ?>
<?php if ($this->session->flashdata('crew_success')): ?><div class="alert alert-success" role="alert"><?= html_escape($this->session->flashdata('crew_success')) ?></div><?php endif; ?>
<div class="card shadow-sm mb-3"><div class="card-body"><div class="row g-3 align-items-end"><div class="col-md-5"><label class="form-label" for="crew-trade-filter">Source trade</label><select class="form-select" id="crew-trade-filter" data-master-filter data-table-target="crew-table" data-column="2"><option value="">All trades</option><?php foreach ($trades as $trade): ?><option value="<?= html_escape($trade) ?>"><?= html_escape($trade) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label" for="crew-status-filter">Status</label><select class="form-select" id="crew-status-filter" data-master-filter data-table-target="crew-table" data-column="7"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select></div><div class="col-md-3"><?php if ($can_manage): ?><a class="btn btn-primary w-100" href="<?= site_url('crews/create') ?>"><i class="bi bi-plus-lg" aria-hidden="true"></i> Add Crew</a><?php endif; ?></div></div></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table id="crew-table" class="table table-striped table-hover align-middle w-100 master-data-table"><thead><tr><th>Code</th><th>Crew Name</th><th>Source Trade</th><th>Labor Crafts</th><th>Total Members</th><th>Calculated Daily Cost</th><th>Currency</th><th>Status</th><th data-dt-order="disable">Actions</th></tr></thead><tbody><?php foreach ($crews as $crew): ?><tr><td><a class="fw-semibold text-decoration-none" href="<?= site_url('crews/'.$crew->crew_id) ?>"><?= html_escape($crew->crew_code) ?></a></td><td><?= html_escape($crew->crew_name ?? '—') ?></td><td><?= html_escape($crew->source_trade ?? '—') ?></td><td><?= number_format($crew->craft_count) ?></td><td><?= number_format($crew->total_members, 4) ?></td><td data-order="<?= html_escape($crew->calculated_daily_cost) ?>"><?= number_format($crew->calculated_daily_cost, 2) ?></td><td><?= html_escape($crew->currency_code ?? '—') ?></td><td><span class="badge text-bg-<?= $crew->is_active ? 'success' : 'secondary' ?>"><?= $crew->is_active ? 'Active' : 'Inactive' ?></span></td><td class="text-nowrap"><a class="btn btn-outline-secondary btn-sm" href="<?= site_url('crews/'.$crew->crew_id) ?>" aria-label="View"><i class="bi bi-eye" aria-hidden="true"></i></a><?php if ($can_manage): ?> <a class="btn btn-outline-primary btn-sm" href="<?= site_url('crews/'.$crew->crew_id.'/edit') ?>" aria-label="Edit"><i class="bi bi-pencil" aria-hidden="true"></i></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
